def _real_active_schools():
    return School.objects.filter(
        status="active",
        is_active=True,
    ).exclude(name="Default School").order_by("name", "id")


def _primary_school():
    """Return the single supported school without relying on its database PK."""
    school, _ = School.objects.get_or_create(
        name=PRIMARY_SCHOOL_NAME,
        defaults={
            "code": PRIMARY_SCHOOL_CODE,
            "address": PRIMARY_SCHOOL_ADDRESS,
            "status": "active",
            "is_active": True,
        },
    )

    updates = []
    for field, value in {
        "code": PRIMARY_SCHOOL_CODE,
        "address": PRIMARY_SCHOOL_ADDRESS,
        "status": "active",
        "is_active": True,
    }.items():
        if getattr(school, field) != value:
            setattr(school, field, value)
            updates.append(field)
    if updates:
        school.save(update_fields=[*updates, "updated_at"])
    return school


def _active_signup_school(school_id):
    if not str(school_id or '').strip().isdigit():
        return None
    return _real_active_schools().filter(pk=int(school_id)).first()


def _signup_school():
    """New accounts are always created under the single supported school."""
    return _primary_school()


def _user_school_calendar_queryset(user):
    """Return the school-owned calendars for the given user.

    Teacher and student schedules should always resolve from the school they are
    assigned to, not from a single global active calendar.
    """
    if not user:
        return SchoolCalendar.objects.none()

    school = getattr(user, 'school_record', None)
    if not school and getattr(user, 'school', None):
        school = School.objects.filter(name=user.school).first()
    if not school:
        return SchoolCalendar.objects.none()

    if user.role == 'teacher':
        queryset = SchoolCalendar.objects.filter(
            Q(sections__school=school, sections__teacher=user) | Q(id=user.school_calendar_id)
        ).distinct()
    elif user.role == 'student':
        queryset = SchoolCalendar.objects.filter(
            Q(enrollments__school=school, enrollments__student=user, enrollments__status__in=('active', 'awaiting_assignment'), enrollments__is_active=True) |
            Q(id=user.school_calendar_id)
        ).distinct()
    else:
        queryset = SchoolCalendar.objects.filter(
            Q(sections__school=school) | Q(enrollments__school=school)
        ).distinct()

    return queryset.order_by('-is_active', '-updated_at', '-created_at')


def _school_for_user(user):
    if not user:
        return None
    if getattr(user, 'school_record_id', None):
        return user.school_record
    school_name = (getattr(user, 'school', None) or '').strip()
    if not school_name:
        return None
    return School.objects.filter(name=school_name).first()


def _school_calendar_for_user(user):
    school = _school_for_user(user)
    if not school:
        return _active_school_calendar_for_new_workflows()
    if getattr(user, 'role', None) == 'teacher':
        calendar = SchoolCalendar.objects.filter(
            sections__school=school,
            sections__teacher=user,
            sections__is_active=True,
        ).order_by('-is_active', '-updated_at', '-created_at').distinct().first()
        if calendar:
            return calendar
    elif getattr(user, 'role', None) == 'student':
        calendar = SchoolCalendar.objects.filter(
            enrollments__school=school,
            enrollments__student=user,
            enrollments__status__in=('active', 'awaiting_assignment'),
            enrollments__is_active=True,
        ).order_by('-is_active', '-updated_at', '-created_at').distinct().first()
        if calendar:
            return calendar
    return SchoolCalendar.objects.filter(sections__school=school).order_by('-is_active', '-updated_at', '-created_at').distinct().first() or _active_school_calendar_for_new_workflows()


def _active_school_calendar_for_new_workflows():
    """Legacy fallback: return the one active calendar only when there is no school context."""
    calendars = SchoolCalendar.objects.filter(is_active=True).order_by('-updated_at', '-created_at')
    if calendars.count() != 1:
        return None
    return calendars.first()


def _teacher_current_sections(teacher, *, include_inactive=False):
    if not teacher:
        return Section.objects.none()
    school = _school_for_user(teacher)
    if school:
        filters = {'teacher': teacher, 'school': school}
        if not include_inactive:
            filters['is_active'] = True
        return Section.objects.filter(**filters).select_related('school', 'school_calendar', 'teacher').order_by('class_name')

    calendar = _active_school_calendar_for_new_workflows()
    if not calendar:
        # Preserve legacy mutation/test fixtures that predate SchoolCalendar;
        # production current-year sections always have an active calendar.
        filters = {'teacher': teacher, 'school_calendar__isnull': True}
        if not include_inactive:
            filters['is_active'] = True
        return Section.objects.filter(**filters)
    filters = {'teacher': teacher, 'school_calendar': calendar}
    if not include_inactive:
        filters['is_active'] = True
    return Section.objects.filter(**filters)


def _student_current_enrollment(user):
    if not user:
        return None
    school = _school_for_user(user)
    if school:
        return (Enrollment.objects.filter(
            student=user, school=school, status='active', is_active=True,
            grade_level=NEW_USER_GRADE_LEVEL, section__is_active=True,
        ).select_related('section__teacher', 'school', 'school_calendar').order_by('id').first())

    calendar = _active_school_calendar_for_new_workflows()
    if not calendar:
        return None
    return (Enrollment.objects.filter(
        student=user, school_calendar=calendar, status='active', is_active=True,
        grade_level=NEW_USER_GRADE_LEVEL, section__is_active=True,
        section__school_calendar=calendar,
    ).select_related('section__teacher', 'school', 'school_calendar').order_by('id').first())


def _student_current_or_awaiting_enrollment(user, school_calendar=None):
    """Resolve only this year's editable enrollment; never fall back to history."""
    if not user:
        return None
    school = _school_for_user(user)
    if school:
        filters = {
            'student': user,
            'school': school,
            'status__in': ('active', 'awaiting_assignment'),
            'grade_level': NEW_USER_GRADE_LEVEL,
        }
        if school_calendar is not None:
            filters['school_calendar'] = school_calendar
        return (Enrollment.objects.filter(**filters)
            .select_related('section__teacher', 'school', 'school_calendar')
            .order_by('id').first())

    calendar = school_calendar or _active_school_calendar_for_new_workflows()
    if not calendar:
        return None
    active_calendar = _active_school_calendar_for_new_workflows()
    if not active_calendar or calendar.id != active_calendar.id:
        return None
    return (Enrollment.objects.filter(
        student=user, school_calendar=calendar,
        status__in=('active', 'awaiting_assignment'),
        grade_level=NEW_USER_GRADE_LEVEL,
    ).select_related('section__teacher', 'school', 'school_calendar').order_by('id').first())


def _student_current_sections(user):
    enrollment = _student_current_enrollment(user)
    return Section.objects.filter(pk=enrollment.section_id) if enrollment and enrollment.section_id else Section.objects.none()


def _active_canonical_section(grade_level, section_name, school=None, school_calendar=None, section_id=None):
    """Resolve a selectable canonical class; signup never creates one."""
    filters = {'is_active': True}
    if grade_level:
        filters['grade_level__iexact'] = str(grade_level).strip()
    if section_id:
        filters['pk'] = section_id
    else:
        filters['section__iexact'] = str(section_name or '').strip()
    queryset = Section.objects.filter(**filters)
    if school is not None:
        queryset = queryset.filter(school=school)
    if school_calendar is not None:
        queryset = queryset.filter(school_calendar=school_calendar)
    return queryset.select_related('school', 'school_calendar', 'teacher').first()


def _signup_section_queryset(role, school=None, grade_level=None):
    if school is not None:
        active_calendar = SchoolCalendar.objects.filter(sections__school=school).order_by('-is_active', '-updated_at', '-created_at').distinct().first() or _active_school_calendar_for_new_workflows()
    else:
        active_calendar = _active_school_calendar_for_new_workflows()
    if not active_calendar:
        return Section.objects.none()
    if school is not None:
        ensure_salawag_grade_two_sections(school, active_calendar)
    qs = Section.objects.filter(
        is_active=True,
        school_calendar=active_calendar,
    ).select_related('teacher', 'school', 'school_calendar').order_by('section')
    if school is not None:
        qs = qs.filter(school=school)
    else:
        qs = qs.filter(school__status='active', school__is_active=True).exclude(school__name='Default School')
    if grade_level:
        qs = qs.filter(grade_level__iexact=str(grade_level).strip())
    if role == 'teacher':
        # Only an active teacher account occupies a Section. Legacy rows that
        # point to archived/non-teacher users remain visible for normalization.
        qs = qs.exclude(teacher__role='teacher', teacher__is_archived=False)
    return qs


def _section_signup_payload(section):
    teacher = getattr(section, 'teacher', None)
    return {
        'id': section.id,
        'school_id': section.school_id,
        'school_name': section.school.name if section.school else '',
        'school_year': section.school_calendar.school_year if section.school_calendar else '',
        'grade_level': section.grade_level,
        'section': section.section,
        'class_name': section.class_name,
        'is_active': section.is_active,
        # The queryset applies role-specific filtering; keep availability
        # explicit so the template does not treat a missing value as false.
        'is_available': bool(section.is_active),
        'has_teacher': section.has_active_teacher(),
        'teacher_name': f"{teacher.first_name} {teacher.last_name}".strip() if teacher else '',
        'student_count': section.get_student_count(),
    }


def _section_selection_context(role):
    grade_map = {grade: [] for grade in SCHOOL_GRADE_LEVELS}
    available_grades = set()
    for section in _signup_section_queryset(role):
        if section.grade_level in grade_map:
            available_grades.add(section.grade_level)
            grade_map.setdefault(section.grade_level, []).append(_section_signup_payload(section))
    signup_grades = [
        {'label': grade, 'value': grade, 'is_available': grade in available_grades}
        for grade in SCHOOL_GRADE_LEVELS
    ]
    return signup_grades, grade_map


def _signup_section_for_request(data, role):
    # Signup is scoped to the school explicitly selected by the registrant;
    # the active school year and section still provide the authoritative
    # availability/ownership checks below.
    school = _active_signup_school(data.get('school_id')) or _signup_school()
    if not school:
        return None, None, 'Salawag Elementary School is not available for signup.'

    active_calendar = _active_school_calendar_for_new_workflows()
    if not active_calendar:
        return school, None, 'No active School Year is configured. Please contact an administrator.'

    section_value = str(data.get('section') or '').strip()
    if not section_value:
        return school, None, 'Choose an available Section.'
    section_id = int(section_value) if section_value.isdigit() else None
    # Students are always enrolled in Grade 2; client-submitted grades are not trusted.
    grade_level = NEW_USER_GRADE_LEVEL
    section = _active_canonical_section(
        grade_level,
        section_value if section_id is None else '',
        school=school,
        school_calendar=active_calendar,
        section_id=section_id,
    )
    if not section:
        return school, None, 'The selected Section is not available for the active School Year.'
    return school, section, None


