def _official_crla_material_keys_for_student(student, on_date=None):
    if not student or getattr(student, 'role', '') != 'student':
        return []

    active_phase = _official_crla_assessment_phase(student, on_date=on_date)
    if active_phase == 'pretest':
        return [key for key in _official_crla_materials_for_phase('pretest').values_list('system_assessment_key', flat=True) if key]
    if active_phase == 'midtest':
        return [key for key in _official_crla_materials_for_phase('midtest').values_list('system_assessment_key', flat=True) if key]
    if active_phase == 'posttest' and _student_is_eosy_crla_eligible(student):
        return [key for key in _official_crla_materials_for_phase('posttest').values_list('system_assessment_key', flat=True) if key]
    return []


def _published_crla_material_for_student(student):
    if not student or getattr(student, 'role', '') != 'student':
        return None

    sections = [
        section
        for section in Section.objects.filter(is_active=True)
        if section.has_student(student, active_only=True)
    ]
    if not sections:
        return None

    return Material.objects.filter(
        Q(section__in=sections)
        | Q(assigned_sections__in=sections)
        | Q(courses__sections__in=sections),
        assessment_kind='crla',
        type__in=['assessment', 'both'],
        status='published',
        student_access=True,
        is_active=True,
    ).distinct().order_by('created_at', 'id').first()

def _parse_prefixed_id(val):
    """
    Robustly extract an integer ID from a value that might be 
    prefixed (e.g., 'material-123', 'assessment-45') or a raw ID.
    Returns (prefix, integer_id).
    """
    if val is None:
        return None, None
    if isinstance(val, int):
        return None, val
    
    s = str(val).strip()
    if not s or s.lower() == 'null' or s.lower() == 'undefined':
        return None, None
        
    if '-' in s:
        parts = s.split('-', 1)
        prefix = parts[0].lower()
        try:
            return prefix, int(parts[1])
        except (ValueError, TypeError):
            return prefix, None
    
    try:
        return None, int(s)
    except (ValueError, TypeError):
        return None, None

