@csrf_protect
@require_http_methods(["POST"])
def verify_student_otp(request):
    try:
        otp = request.POST.get('otp', '').strip()
        logger.debug("VERIFY STUDENT OTP DATA keys=%s", sorted(list(request.POST.keys())))
        logger.debug("VERIFY STUDENT OTP SESSION KEYS=%s", sorted(list(request.session.keys())))
        if not otp:
            return JsonResponse({'success': False, 'error': 'OTP is required'}, status=400)

        pending = request.session.get('pending_student_signup')
        expected_otp = request.session.get('pending_student_signup_otp')
        otp_created = request.session.get('pending_student_signup_otp_created')
        logger.debug(
            "VERIFY STUDENT OTP LOOKUP pending=%s expected_otp_present=%s otp_created=%s",
            bool(pending),
            bool(expected_otp),
            otp_created,
        )

        if not pending or not expected_otp or not otp_created:
            return JsonResponse({'success': False, 'error': 'Your registration session expired or was not started. Please submit the signup form again to receive a new OTP.'}, status=400)

        if time.time() - otp_created > 10 * 60:
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'OTP expired. Please request a new code.'}, status=400)

        if otp != expected_otp:
            return JsonResponse({'success': False, 'error': 'Invalid OTP. Please try again.'}, status=400)

        birth_date_error = _signup_birth_date_error(pending, 'student')
        if birth_date_error:
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': birth_date_error}, status=400)

        pending_email = _normalize_registration_value(pending.get('email'))
        pending_lrn = _normalize_registration_value(pending.get('lrn'))
        pending_grade = _normalize_registration_value(pending.get('grade_level'))
        pending_section_name = _normalize_registration_value(pending.get('section'))
        logger.debug(
            "VERIFY STUDENT OTP PENDING email=%s lrn=%s grade_level=%s section=%s",
            pending_email,
            pending_lrn,
            pending.get('grade_level', ''),
            pending.get('section', ''),
        )

        if User.objects.filter(email__iexact=pending_email, is_archived=False).exists():
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'Email already registered'}, status=400)

        lrn = pending_lrn
        if lrn and not re.fullmatch(r'\d{12}', lrn):
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'LRN must contain exactly 12 digits.'}, status=400)
        if lrn and User.objects.filter(lrn__iexact=lrn, is_archived=False).exists():
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'LRN is already registered'}, status=400)

        school, selected_section, signup_error = _signup_section_for_request(pending, 'student')
        if signup_error:
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'The selected grade and section are no longer available.'}, status=400)

        custom_id = generate_custom_id('student', selected_section.grade_level)
        logger.debug("VERIFY STUDENT OTP BEFORE USER CREATE custom_id=%s email=%s grade_level=%s lrn_present=%s",
                     custom_id, pending.get('email'), pending.get('grade_level', ''), bool(lrn))
        user = None
        for _attempt in range(5):
            try:
                # Isolate a custom-ID collision so a retry remains valid even
                # when this view is called inside an outer transaction (tests
                # and integrations commonly do this).
                with transaction.atomic():
                    user = User.objects.create(
                        custom_id=custom_id,
                        role='student',
                        first_name=pending['first_name'],
                        last_name=pending['last_name'],
                        email=pending['email'],
                        middle_initial=pending.get('middle_initial', ''),
                        suffix=pending.get('suffix', ''),
                        sex=pending['sex'],
                        birth_month=pending['birth_month'],
                        birth_day=pending['birth_day'],
                        birth_year=pending['birth_year'],
                        password_hash=pending['password_hash'],
                        contact_no=pending.get('contact_no', ''),
                        school=school.name,
                        school_record=school,
                        school_calendar=selected_section.school_calendar,
                        lrn=lrn or None,
                        grade_level=selected_section.grade_level,
                        section=selected_section.section,
                        reading_level=pending.get('reading_level', ''),
                    )
                break
            except IntegrityError:
                custom_id = generate_custom_id('student', selected_section.grade_level)
        if user is None:
            logger.error("VERIFY STUDENT OTP could not allocate unique custom ID")
            _clear_pending_student_signup(request)
            return JsonResponse({'success': False, 'error': 'A student with this PABASA ID already exists. Please try again.'}, status=400)

        logger.debug("VERIFY STUDENT OTP AFTER USER CREATE user_id=%s custom_id=%s", user.id, user.custom_id)
        # Student signup resolves the existing canonical section above and
        # never creates school structure or an alternate class.
        try:
            # Keep membership creation on the established Section API so
            # Enrollment, the legacy students JSON, and student tags stay synchronized.
            selected_section.add_student(user)
        except Exception:
            logger.exception("VERIFY STUDENT OTP automatic enrollment failed user_id=%s section_id=%s", user.id, selected_section.id)
            user.delete()
            return JsonResponse({'success': False, 'error': 'Unable to enroll the student in the selected class.'}, status=400)
        try:
            send_student_confirmation_email(request, user)
        except Exception:
            logger.exception("VERIFY STUDENT OTP confirmation email failed for user_id=%s", user.id)
        try:
            _notify_admins(
                'New student account',
                f'{user.first_name} {user.last_name} created a student account.',
                'success',
                reverse('admin_student_detail', args=[user.id]),
                user,
            )
        except Exception:
            logger.exception("VERIFY STUDENT OTP admin notification failed for user_id=%s", user.id)
        _clear_pending_student_signup(request)

        return JsonResponse({
            'success': True,
            'message': 'Student registered successfully',
            'custom_id': custom_id
        })

    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


