@csrf_protect
@require_http_methods(["POST"])
def login_user(request):
    """Authenticate user and create session"""
    try:
        data = request.POST
        custom_id = data.get('custom_id', '').strip().upper()
        password = data.get('password', '')

        if not custom_id or not password:
            return JsonResponse({'success': False, 'error': 'Custom ID and password are required'}, status=400)
        
        # Find user by custom_id
        try:
            user = User.objects.get(custom_id__iexact=custom_id)
        except User.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'Invalid custom ID or password'}, status=401)
        
        # Verify password
        if not user.check_password(password):
            return JsonResponse({'success': False, 'error': 'Invalid custom ID or password'}, status=401)

        if getattr(user, 'is_archived', False) or getattr(user, 'account_status', '') == 'archived':
            return JsonResponse({'success': False, 'error': 'This account has been archived. Please contact an administrator.'}, status=403)

        # Verify account activity status
        if user.role == 'admin':
            # Admins are considered active by default.
            pass
        elif user.role == 'teacher':
            # Teachers are considered active by default unless explicitly deactivated
            pass
        elif user.role == 'student':
            # Students are considered active by default
            pass
            
        if not request.session.session_key:
            request.session.save()
        session_key = request.session.session_key
        if user.role == 'student':
            # Student auth cookies are browser-session cookies, so a client
            # clock change cannot make the browser discard a valid session.
            # Django's server-side session expiry remains authoritative.
            request.session.set_expiry(0)
            if not claim_student_session(user.id, session_key):
                return JsonResponse({'success': False, 'error': 'Account Already in Use: This student account is currently logged in on another device. Please log out from that device before logging in here.'}, status=409)

        # Create session
        request.session['user_id'] = user.id
        request.session['custom_id'] = user.custom_id
        request.session['user_role'] = user.role
        request.session['first_name'] = user.first_name
        request.session['last_name'] = user.last_name
        request.session['email'] = user.email
        request.session['login_at'] = timezone.now().isoformat()
        
        if user.role == 'admin':
            redirect_url = '/dashboard/admin/'
        elif user.role == 'principal':
            redirect_url = reverse(
                'principal_change_temporary_password' if user.must_change_password else 'dashboard_principal'
            )
        elif user.role == 'teacher':
            redirect_url = '/dashboard/teacher/'
        else:
            redirect_url = '/dashboard/'
        
        return JsonResponse({
            'success': True,
            'message': 'Login successful',
            'role': user.role,
            'redirect_url': redirect_url,
            'custom_id': user.custom_id,
            'email': user.email,
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@csrf_protect
@require_http_methods(["GET", "POST"])
def principal_change_temporary_password(request):
    if not _check_auth(request) or request.session.get('user_role') != 'principal':
        return redirect('auth')

    user = User.objects.filter(
        id=request.session.get('user_id'),
        role='principal',
        is_archived=False,
    ).first()
    if not user:
        request.session.flush()
        return redirect('auth')
    if not user.must_change_password:
        return redirect('dashboard_principal')

    context = {'principal_id': user.custom_id}
    if request.method == 'POST':
        new_password = request.POST.get('new_password', '')
        confirm_password = request.POST.get('confirm_password', '')

        if not new_password or not confirm_password:
            context['error_message'] = 'New Password and Confirm New Password are required.'
        elif new_password != confirm_password:
            context['error_message'] = 'New Password and Confirm New Password do not match.'
        elif user.check_password(new_password):
            context['error_message'] = 'Choose a new private password instead of the temporary password.'
        else:
            try:
                validate_password(new_password, user=user)
            except ValidationError as exc:
                context['password_errors'] = exc.messages
            else:
                user.set_password(new_password)
                user.must_change_password = False
                user.save(update_fields=['password_hash', 'must_change_password', 'updated_at'])
                request.session.cycle_key()
                request.session['login_at'] = timezone.now().isoformat()
                request.session.modified = True
                return redirect('dashboard_principal')

    return render(request, 'pabasa_app/principal_change_temporary_password.html', context)

def logout_user(request):
    """Logout user and destroy session"""
    if request.session.get('user_role') == 'student':
        release_student_session(request.session.get('user_id'), request.session.session_key)
    request.session.flush()
    return redirect('home')

def _check_auth(request):
    """Check if user is authenticated"""
    return 'user_id' in request.session


def _derive_dashboard_greeting_name(first_name='', full_name=''):
    """Return the display name to use for the student dashboard greeting."""
    first_name = (first_name or '').strip()
    if first_name:
        return first_name

    full_name = (full_name or '').strip()
    if full_name:
        return full_name.split()[0]

    return 'Student'


# REPLACE the entire _dashboard_context function:
def _dashboard_context(request, nav_role=None, extra=None):
    perf_started_at = time.perf_counter()
    perf_role = nav_role or request.session.get('user_role', 'student')
    perf_enabled = perf_role == 'student'
    perf_marks = {}

    def perf_mark(label):
        if perf_enabled:
            perf_marks[label] = time.perf_counter()

    def perf_log(label, start_label, extra_data=None):
        if not perf_enabled:
            return
        start = perf_marks.get(start_label)
        if start is None:
            return
        payload = {
            'stage': label,
            'elapsed_ms': round((time.perf_counter() - start) * 1000, 2),
        }
        if extra_data:
            payload.update(extra_data)
        logger.warning("PABASA_DASHBOARD_PROFILE %s", payload)

    user = User.objects.filter(id=request.session.get('user_id')).first()
    perf_mark('after_user_load')
    first_name = user.first_name if user else request.session.get('first_name', '')
    last_name = user.last_name if user else request.session.get('last_name', '')
    _mi = user.middle_initial if user else ''
    _sx = user.suffix if user else ''
    _name_parts = [first_name, _mi, last_name, _sx]
    full_name = ' '.join(p for p in _name_parts if p).strip() or request.session.get('custom_id', 'User')
    teacher_role = ''
    initials = "".join(part[:1] for part in full_name.split()[:2]).upper() or "PA"
    birthday_display = ""
    if user and user.birth_month and user.birth_day and user.birth_year:
        birthday_display = f"{int(user.birth_month):02d}/{int(user.birth_day):02d}/{user.birth_year}"
    profile_photo_url = None
    username = ''

    if user:
        if user.role == 'teacher':
            teacher_role = user.teacher_role or ''

        username = f"{user.first_name}_{user.last_name}".lower().replace(" ", "_")
        if PROFILE_PHOTOS_DIR.exists():
            for file in PROFILE_PHOTOS_DIR.glob(f'profile_photo_{username}.*'):
                profile_photo_url = f'/static/pabasa_app/uploads/profiles/{file.name}'
                break

    joined_classes = []
    user_role = user.role if user else request.session.get('user_role', 'student')
    effective_role = nav_role or user_role
    student_sections = []

    if user and user.role == 'student':
        perf_mark('student_branch_start')
        student_user = user
        perf_mark('student_sections_query_start')

        active_sections_count = Section.objects.filter(is_active=True).count()
        perf_mark('student_sections_query_execute_start')
        student_sections = list(_student_current_sections(student_user).select_related('school_calendar').order_by('class_name'))
        perf_log('student_sections_query_execute_complete', 'student_sections_query_execute_start', {
            'student_sections_count': len(student_sections),
        })

        perf_log('student_sections_query_complete', 'student_sections_query_start', {
            'active_sections_count': active_sections_count,
            'student_sections_count': len(student_sections),
            'student_section_query': 'enrollment_active',
        })

        perf_mark('joined_classes_start')
        for cls in student_sections:
            joined_classes.append({
                'id': cls.id,
                'section_id': cls.id,
                'code': cls.class_code,
                'name': cls.class_name,
                'student_count': _section_student_count(cls),
            })
        perf_log('joined_classes_built', 'joined_classes_start', {
            'joined_classes_count': len(joined_classes),
        })
    # Catch anyone who is not a student (Teachers and Admins) so they can see 
    # the sections they have created/own in the sidebar and dashboard.
    elif user and (user.role in ['teacher', 'admin'] or effective_role in ['teacher', 'admin']):
        classes = _teacher_current_sections(user).order_by('class_name')
        for cls in classes:
            joined_classes.append({
                'id': cls.id,
                'section_id': cls.id,
                'code': cls.class_code,
                'name': cls.class_name,
                'student_count': _section_student_count(cls),
                'subject': cls.subject,
            })

    context = {
        'nav_role': nav_role or request.session.get('user_role', 'student'),
        'user_id': request.session.get('custom_id'),
        'first_name': first_name,
        'last_name': last_name,
        'user_full_name': full_name,
        'dashboard_greeting_name': _derive_dashboard_greeting_name(first_name, full_name),
        'email': request.session.get('email', ''),
        'teacher_role': teacher_role,
        'role_display': teacher_role or (nav_role or request.session.get('user_role', 'student')).title(),
        'profile_photo_url': profile_photo_url,
        'initials': initials,
        'joined_classes': joined_classes,
        'active_teacher_class_count': len(joined_classes),
    }
    if user and user.role == 'student':
        context['student_reading_level'] = (
            _reader_assessment_state(user).get('reader_classification')
            or getattr(user, 'reading_level', '')
            or 'Pending'
        )
    perf_mark('teacher_courses_start')
    # Classes are the source of truth for personal Courses. Each active class
    # is represented as a course card without requiring a legacy Course row.
    try:
        teacher_courses = []
        if user and (user.role in ['teacher', 'admin'] or effective_role in ['teacher', 'admin']):
            class_qs = _teacher_current_sections(user).order_by('-created_at')
            teacher_courses = [_section_course_payload(section) for section in class_qs]
    except Exception:
        teacher_courses = []
    context['teacher_courses'] = teacher_courses
    perf_log('teacher_courses_built', 'teacher_courses_start', {
        'teacher_courses_count': len(teacher_courses),
    })
    # Compute an account activity status label + class for UI chips
    account_status_label = 'Unknown'
    account_status_class = ''
    account_status_tooltip = ''
    try:
        if user:
            # Default: pending if teacher has no classes/materials/activity
            last_activity = None
            has_activity = False
            if user.role == 'teacher':
                tp_user = user
                # Check for classes, materials, and joined students stored in sections
                has_classes = _teacher_current_sections(tp_user).exists()
                # Materials are now stored in the `materials` table. Detect
                # posted materials by checking the Section->Material relation.
                has_materials = Material.objects.filter(
                        Q(section__teacher=tp_user) | Q(assigned_sections__teacher=tp_user) | Q(assessment__teacher=tp_user),
                        is_active=True
                    ).distinct().exists()
                has_joined_students = any(
                    _section_student_count(cls) > 0
                    for cls in _teacher_current_sections(tp_user)
                )
                has_attempts = Assessment.objects.filter(teacher=tp_user, source_assessment__isnull=True).exists()
                has_activity = has_classes or has_materials or has_joined_students or has_attempts

                # Get latest timestamps
                candidate_dates = []
                if getattr(tp_user, 'updated_at', None):
                    candidate_dates.append(tp_user.updated_at)
                cls_max = Section.objects.filter(teacher=tp_user).aggregate(m=Max('updated_at'))['m']
                if cls_max:
                    candidate_dates.append(cls_max)
                asm_max = Assessment.objects.filter(teacher=tp_user, source_assessment__isnull=True).aggregate(m=Max('updated_at'))['m']
                if asm_max:
                    candidate_dates.append(asm_max)
                # Include latest material timestamp for teacher (if any)
                mat_max = Material.objects.filter(
                    Q(section__teacher=tp_user) | Q(assigned_sections__teacher=tp_user) | Q(assessment__teacher=tp_user),
                ).aggregate(m=Max('updated_at'))['m']
                if mat_max:
                    candidate_dates.append(mat_max)
                if candidate_dates:
                    last_activity = max(candidate_dates)

            else:
                # For students, use student user updated or enrollment timestamps
                sp_user = user
                if sp_user:
                    perf_mark('student_activity_start')
                    has_activity = True
                    candidate_dates = [d for d in [getattr(sp_user, 'updated_at', None), getattr(sp_user, 'created_at', None)] if d]
                    if student_sections:
                        candidate_dates.extend(
                            cls.updated_at for cls in student_sections if getattr(cls, 'updated_at', None)
                        )
                    if candidate_dates:
                        last_activity = max(candidate_dates)
                    perf_log('student_activity_built', 'student_activity_start', {
                        'candidate_dates_count': len(candidate_dates),
                        'student_sections_count': len(student_sections),
                    })

            if not has_activity and not last_activity:
                account_status_label = 'Pending'
                account_status_class = 'status-pending'
                account_status_tooltip = 'No activity recorded yet.'
            else:
                now = timezone.now()
                if last_activity:
                    delta = now - last_activity
                    days = delta.days
                    if user.role == 'teacher':
                        # keep existing teacher granularity
                        if days <= 7:
                            account_status_label = 'Active'
                            account_status_class = 'status-active'
                        elif 8 <= days <= 30:
                            account_status_label = 'Idle'
                            account_status_class = 'status-idle'
                        else:
                            account_status_label = 'Inactive'
                            account_status_class = 'status-inactive'
                    else:
                        # Student: Pending (no activity handled earlier), Active = 1-7 days, Inactive = 8+ days
                        if days <= 7:
                            account_status_label = 'Active'
                            account_status_class = 'status-active'
                        else:
                            account_status_label = 'Inactive'
                            account_status_class = 'status-inactive'
                    account_status_tooltip = f'Last activity: {last_activity.strftime("%Y-%m-%d %H:%M")}'
                else:
                    account_status_label = 'Pending'
                    account_status_class = 'status-pending'
                    account_status_tooltip = 'No activity recorded yet.'
    except Exception:
        account_status_label = 'Unknown'
        account_status_class = ''

    context.update({
        'account_status_label': account_status_label,
        'account_status_class': account_status_class,
        'account_status_tooltip': account_status_tooltip,
        'student_theme_slug': (
            user.equipped_theme
            if user and user.role == 'student' and user.equipped_theme in STUDENT_THEME_CATALOG
            else 'sky'
        ),
    })
    perf_mark('student_calendar_start')
    if nav_role in ('student', 'teacher'):
        print("BEFORE _selected_school_calendar")
        active_school_calendar, _, _ = _selected_school_calendar(request)
        print("AFTER _selected_school_calendar")
        print("BEFORE _calendar_current_term")
        current_term = _calendar_current_term(active_school_calendar) if active_school_calendar else None
        print("AFTER _calendar_current_term")
        print("BEFORE _calendar_month_view")
        calendar_widget = _calendar_month_view(active_school_calendar)
        print("AFTER _calendar_month_view")
        print("AFTER_CALENDAR_COMPLETE")
        student_calendar_events = []
        if active_school_calendar:
            student_calendar_events = _calendar_events_for_audience(active_school_calendar, user)
        context['active_school_calendar'] = active_school_calendar
        print("CONTEXT_KEY_DONE", "active_school_calendar")
        context['student_calendar_school_year'] = _calendar_school_year_label(active_school_calendar)
        print("CONTEXT_KEY_DONE", "student_calendar_school_year")
        context['student_calendar_current_term'] = f"Term {current_term}" if current_term else (
            f"Term {active_school_calendar.current_term}" if active_school_calendar and active_school_calendar.current_term else 'Not set'
        )
        print("CONTEXT_KEY_DONE", "student_calendar_current_term")
        context['student_calendar_events_json'] = json.dumps(student_calendar_events)
        print("CONTEXT_KEY_DONE", "student_calendar_events_json")
        context['month_name'] = calendar_widget.get('month_name')
        print("CONTEXT_KEY_DONE", "month_name")
        context['month_year_label'] = calendar_widget.get('month_year_label')
        print("CONTEXT_KEY_DONE", "month_year_label")
        context['today'] = calendar_widget.get('today')
        print("CONTEXT_KEY_DONE", "today")
        context['month_weeks'] = calendar_widget.get('month_weeks')
        context['calendar_weekday_labels'] = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        print("CONTEXT_KEY_DONE", "month_weeks")
        context['calendar_legend'] = calendar_widget.get('calendar_legend')
        context['student_calendar_legend'] = [
            ('school_opening', 'Opening Block'),
            ('pre_assessment', 'Pre-Assessment'),
            ('midline_assessment', 'Mid-Assessment'),
            ('post_assessment', 'Post-Assessment'),
            ('school_closing', 'Closing Block'),
            ('aral_1', 'ARAL 1 — After Class'),
            ('aral_2', 'ARAL 2 — End of Term (last 1–5 days)'),
        ]
        print("CONTEXT_KEY_DONE", "calendar_legend")
        perf_log('student_calendar_built', 'student_calendar_start', {
            'student_calendar_events_count': len(student_calendar_events),
        })
    if extra:
        perf_mark('extra_context_start')
        context.update(extra)
        perf_log('extra_context_built', 'extra_context_start', {
            'extra_keys': sorted(list(extra.keys())) if isinstance(extra, dict) else [],
        })
        print("CONTEXT_KEY_DONE", "extra")
    if perf_enabled:
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_total',
                'elapsed_ms': round((time.perf_counter() - perf_started_at) * 1000, 2),
                'student_sections_count': len(student_sections),
                'joined_classes_count': len(joined_classes),
                'has_teacher_courses': bool(context.get('teacher_courses')),
            },
        )
    print("CONTEXT_BUILD_COMPLETE")
    return context

def home(request):
    animation_dir = Path(__file__).resolve().parent / 'static' / 'pabasa_app' / 'animation' / 'Reading'
    reading_animation_frames = []

    if animation_dir.exists():
        def frame_sort_key(path: Path):
            match = re.search(r'(\d+)', path.stem)
            return (int(match.group(1)) if match else float('inf'), path.stem.lower())

        reading_animation_frames = [
            f"pabasa_app/animation/Reading/{frame.name}"
            for frame in sorted(animation_dir.glob('*.png'), key=frame_sort_key)
        ]

    return render(request, 'pabasa_app/home.html', {
        'reading_animation_frames': reading_animation_frames,
        'reading_animation_first_frame': reading_animation_frames[0] if reading_animation_frames else '',
    })

