@require_http_methods(["GET"])
def student_signup_sections(request):
    role = str(request.GET.get('role', 'student')).strip().lower()
    if role not in {'teacher', 'student'}:
        return JsonResponse({'success': True, 'grades': [], 'sections': []})
    school = _active_signup_school(request.GET.get('school_id')) or _signup_school()
    if not school:
        return JsonResponse({'success': True, 'grades': [], 'sections': []})
    active_calendar = _active_school_calendar_for_new_workflows()
    if not active_calendar:
        return JsonResponse({
            'success': False,
            'error': 'No active School Year is configured. Please contact an administrator.',
            'sections': [],
        }, status=409)
    grade_level = str(request.GET.get('grade_level') or '').strip()
    queryset = _signup_section_queryset(role, school=school, grade_level=grade_level or None)
    sections = [_section_signup_payload(section) for section in queryset] if grade_level else []
    grades = sorted({section.grade_level for section in _signup_section_queryset(role, school=school)})
    return JsonResponse({
        'success': True,
        'school_year': active_calendar.school_year,
        'grades': [{'value': grade, 'label': grade} for grade in grades],
        'sections': sections,
    })

def dashboard(request):
    logger.warning(
        "PABASA_DASHBOARD_PROFILE %s",
        {
            'stage': 'dashboard_view_entry',
            'method': request.method,
            'path': request.path,
            'query': request.META.get('QUERY_STRING', ''),
            'session_has_user_id': 'user_id' in request.session,
            'session_user_role': request.session.get('user_role'),
        },
    )
    render_started_at = time.perf_counter()

    if not _check_auth(request):
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_redirect_unauthenticated',
                'path': request.path,
            },
        )
        return redirect('auth')
    if request.session.get('user_role') != 'student':
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_redirect_wrong_role',
                'requested_role': request.session.get('user_role'),
            },
        )
        return redirect('auth')
    dashboard_user = _current_user(request)
    if not dashboard_user or dashboard_user.is_archived or dashboard_user.account_status == 'archived':
        request.session.flush()
        return redirect('auth')

    context = None
    try:
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_context_start',
            },
        )
        context = _dashboard_context(request, 'student')
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_context_complete',
                'context_keys': len(context) if isinstance(context, dict) else None,
                'context_key_names': sorted(context.keys()) if isinstance(context, dict) else None,
                'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
            },
        )
    except Exception as exc:
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_context_exception',
                'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
                'exception_type': type(exc).__name__,
                'exception_message': str(exc),
            },
        )
        raise

    logger.warning(
        "PABASA_DASHBOARD_PROFILE %s",
        {
            'stage': 'before_render_dashboard_html',
            'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
            'context_keys': len(context),
            'template_name': 'pabasa_app/dashboard.html',
        },
    )
    logger.warning(
        "PABASA_DASHBOARD_PROFILE %s",
        {
            'stage': 'before_dashboard_render',
            'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
        },
    )
    try:
        print("DASHBOARD_BEFORE_RENDER")
        response = render(request, 'pabasa_app/dashboard.html', context)
        print("DASHBOARD_AFTER_RENDER")
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'after_dashboard_render',
                'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
                'response_status': getattr(response, 'status_code', None),
                'response_content_length': len(response.content) if hasattr(response, 'content') else None,
            },
        )
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_total_render',
                'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
            },
        )
        return response
    except Exception as exc:
        logger.warning(
            "PABASA_DASHBOARD_PROFILE %s",
            {
                'stage': 'dashboard_render_exception',
                'elapsed_ms': round((time.perf_counter() - render_started_at) * 1000, 2),
                'exception_type': type(exc).__name__,
                'exception_message': str(exc),
            },
        )
        raise

