@admin_required
@require_http_methods(["GET", "POST"])
def admin_principal_edit(request, user_id):
    user = _get_managed_user(user_id, 'principal')
    if not user:
        return redirect('admin_principals')

    school_info = _get_profile_dict(user, 'principal_school_info') or {}
    profile_info = _get_profile_dict(user, 'principal_profile_info') or {}
    if not isinstance(school_info, dict):
        school_info = {}
    if not isinstance(profile_info, dict):
        profile_info = {}

    if request.method == 'POST':
        email = request.POST.get('email', '').strip().lower()
        school_name = user.school_record.name if user.school_record_id else (user.school or '').strip()
        contact_no = request.POST.get('contact_no', '').strip()

        context = _admin_user_template_context(request, user, 'Edit Principal')
        context.update({'school_info': school_info, 'principal_profile_info': profile_info})

        if not request.POST.get('first_name', '').strip() or not request.POST.get('last_name', '').strip():
            context['error_message'] = 'First name and last name are required.'
            return render(request, 'pabasa_app/admin_principal_edit.html', context, status=400)
        if not email or not school_name:
            context['error_message'] = 'School ownership and email are required.'
            return render(request, 'pabasa_app/admin_principal_edit.html', context, status=400)
        if User.objects.filter(email__iexact=email).exclude(id=user.id).exists():
            context['error_message'] = 'Email is already used by another account.'
            return render(request, 'pabasa_app/admin_principal_edit.html', context, status=400)

        try:
            user.first_name = request.POST.get('first_name', '').strip()
            user.middle_initial = request.POST.get('middle_initial', '').strip()[:1]
            user.last_name = request.POST.get('last_name', '').strip()
            user.suffix = request.POST.get('suffix', '').strip()
            user.email = email
            user.contact_no = contact_no
            user.school = user.school_record.name if user.school_record_id else school_name
            user.save(update_fields=['first_name', 'middle_initial', 'last_name', 'suffix', 'email', 'contact_no', 'school', 'updated_at'])

            profile_info.update({
                'position': request.POST.get('position', '').strip() or 'Principal',
                'full_name': _admin_user_full_name(user),
            })
            _set_profile_dict(user, 'principal_profile_info', profile_info)
            return redirect('admin_principal_detail', user_id=user.id)
        except ValueError as exc:
            context['error_message'] = str(exc)
            return render(request, 'pabasa_app/admin_principal_edit.html', context, status=400)

    context = _admin_user_template_context(request, user, 'Edit Principal')
    context.update({'school_info': school_info, 'principal_profile_info': profile_info})
    return render(request, 'pabasa_app/admin_principal_edit.html', context)


@admin_required
@require_http_methods(["POST"])
def admin_principal_reset_password(request, user_id):
    user = _get_managed_user(user_id, 'principal')
    if not user:
        return redirect('admin_principals')
    if user.is_archived:
        messages.warning(request, 'An inactive Principal account cannot have its password reset.')
        return redirect('admin_principal_detail', user_id=user.id)

    with transaction.atomic():
        locked_user = User.objects.select_for_update().select_related('school_record').get(
            id=user.id,
            role='principal',
        )
        temporary_password = _principal_temporary_password(locked_user.last_name)
        locked_user.set_password(temporary_password)
        locked_user.must_change_password = True
        locked_user.save(update_fields=['password_hash', 'must_change_password', 'updated_at'])

    school_name = locked_user.school_record.name if locked_user.school_record_id else (locked_user.school or '')
    email_sent = _try_send_principal_credentials_email(
        request,
        locked_user,
        school_name,
        temporary_password,
        is_reset=True,
    )
    if email_sent:
        messages.success(
            request,
            "Principal password reset successfully. The temporary credentials were sent to the Principal's email.",
        )
    else:
        messages.warning(
            request,
            'Principal password reset successfully, but the temporary credentials email could not be sent. '
            'SMTP configuration is required before the Principal can receive the new password.',
        )
    return redirect('admin_principal_detail', user_id=locked_user.id)

def _admin_edit_user(request, user_id, role):
    user = _get_managed_user(user_id, role)
    if not user:
        return redirect(_admin_user_redirect_name(role))

    if request.method == 'POST':
        email = request.POST.get('email', '').strip()
        username = request.POST.get('custom_id', '').strip()
        if not username:
            context = _admin_user_template_context(request, user, f'Edit {role.title()}')
            context['error_message'] = 'Username is required.'
            return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
        if User.objects.filter(custom_id__iexact=username).exclude(id=user.id).exists():
            context = _admin_user_template_context(request, user, f'Edit {role.title()}')
            context['error_message'] = 'Username is already used by another account.'
            return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
        if email and User.objects.filter(email__iexact=email).exclude(id=user.id).exists():
            context = _admin_user_template_context(request, user, f'Edit {role.title()}')
            context['error_message'] = 'Email is already used by another account.'
            return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)

        destination_grade = str(request.POST.get('grade_level') or '').strip()
        destination_section_value = str(request.POST.get('section') or '').strip()
        destination_section = None
        if destination_section_value.isdigit():
            destination_section = Section.objects.filter(pk=destination_section_value).first()
        elif destination_grade and destination_section_value:
            destination_section = _active_canonical_section(destination_grade, destination_section_value)

        if role == 'teacher' and (destination_grade or destination_section_value):
            if destination_grade and destination_grade not in SCHOOL_GRADE_LEVELS:
                context = _admin_user_template_context(request, user, 'Edit Teacher')
                context['error_message'] = 'Choose a valid grade level and section.'
                context['available_sections'] = _signup_section_queryset('teacher')
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('teacher', grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            if not destination_section:
                context = _admin_user_template_context(request, user, 'Edit Teacher')
                context['error_message'] = 'The selected section is unavailable.'
                context['available_sections'] = _signup_section_queryset('teacher')
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('teacher', grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            if user.school_record_id and destination_section.school_id != user.school_record_id:
                context = _admin_user_template_context(request, user, 'Edit Teacher')
                context['error_message'] = 'A Teacher can only be assigned within the Teacher\'s School.'
                context['available_sections'] = _signup_section_queryset('teacher', school=user.school_record)
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('teacher', school=user.school_record, grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            with transaction.atomic():
                destination_section = Section.objects.select_for_update().get(pk=destination_section.pk)
                occupied_by = Section.objects.select_for_update().filter(
                    teacher=user,
                    school_calendar_id=destination_section.school_calendar_id,
                    is_active=True,
                    grade_level=NEW_USER_GRADE_LEVEL,
                ).exclude(pk=destination_section.pk).first()
                if occupied_by:
                    occupied_by.unassign_teacher()
                if destination_section.teacher_id and destination_section.teacher_id != user.id:
                    replace = str(request.POST.get('replace_teacher') or '').strip().lower() in {'1', 'true', 'yes', 'on'}
                    if not replace:
                        context = _admin_user_template_context(request, user, 'Edit Teacher')
                        context['warning_message'] = (
                            f"{destination_section.grade_level} - {destination_section.section} is already assigned to "
                            f"{destination_section.active_teacher_name() or 'another teacher'}."
                        )
                        context['pending_destination_section_id'] = destination_section.id
                        context['warning_destination_grade_level'] = destination_section.grade_level
                        context['available_sections'] = _signup_section_queryset('teacher')
                        context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('teacher', grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                        context['school_grades'] = SCHOOL_GRADE_LEVELS
                        return render(request, 'pabasa_app/admin_user_edit.html', context, status=409)
                    destination_section.unassign_teacher()
                destination_section.teacher = user
                destination_section.save(update_fields=['teacher', 'updated_at'])

        if role == 'student' and (destination_grade or destination_section_value):
            if destination_grade and destination_grade not in SCHOOL_GRADE_LEVELS:
                context = _admin_user_template_context(request, user, 'Edit Student')
                context['error_message'] = 'Choose a valid grade level and section.'
                context['available_sections'] = _signup_section_queryset('student')
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('student', grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            if not destination_section:
                context = _admin_user_template_context(request, user, 'Edit Student')
                context['error_message'] = 'The selected section is unavailable.'
                context['available_sections'] = _signup_section_queryset('student')
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('student', grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            if user.school_record_id and destination_section.school_id != user.school_record_id:
                context = _admin_user_template_context(request, user, 'Edit Student')
                context['error_message'] = 'A Student can only be enrolled within the Student\'s School.'
                context['available_sections'] = _signup_section_queryset('student', school=user.school_record)
                context['all_sections_by_grade'] = {grade: list(_signup_section_queryset('student', school=user.school_record, grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            current_enrollment = _student_current_or_awaiting_enrollment(user, destination_section.school_calendar)
            if not current_enrollment or current_enrollment.school_calendar_id != destination_section.school_calendar_id:
                context = _admin_user_template_context(request, user, 'Edit Student')
                context['error_message'] = 'The student has no current enrollment in the selected school year.'
                return render(request, 'pabasa_app/admin_user_edit.html', context, status=400)
            if current_enrollment.section_id != destination_section.id:
                with transaction.atomic():
                    destination_section = Section.objects.select_for_update().select_related('school', 'school_calendar', 'teacher').get(pk=destination_section.pk)
                    current_enrollment.section = destination_section
                    current_enrollment.school = destination_section.school
                    current_enrollment.school_calendar = destination_section.school_calendar
                    current_enrollment.grade_level = destination_section.grade_level or NEW_USER_GRADE_LEVEL
                    current_enrollment.assigned_teacher = destination_section.teacher
                    current_enrollment.status = 'active' if destination_section.teacher_id else 'awaiting_assignment'
                    current_enrollment.save()
                    destination_section.sync_legacy_student_fields()
                    user.sync_legacy_student_fields(current_enrollment)

        user.custom_id = username
        user.first_name = request.POST.get('first_name', '').strip()
        user.middle_initial = request.POST.get('middle_initial', '').strip()[:1]
        user.last_name = request.POST.get('last_name', '').strip()
        user.suffix = request.POST.get('suffix', '').strip()
        user.email = email

        user.save()
        return redirect('admin_student_detail' if role == 'student' else 'admin_teacher_detail', user_id=user.id)

    context = _admin_user_template_context(request, user, f'Edit {role.title()}')
    context['available_sections'] = _signup_section_queryset(role)
    context['all_sections_by_grade'] = {grade: list(_signup_section_queryset(role, grade_level=grade)) for grade in SCHOOL_GRADE_LEVELS}
    context['school_grades'] = SCHOOL_GRADE_LEVELS
    context['current_section_id'] = getattr(context.get('current_section'), 'id', None) if context.get('current_section') else None
    return render(request, 'pabasa_app/admin_user_edit.html', context)

