@admin_required
@require_http_methods(["GET", "POST"])
def admin_school_detail(request, school_id):
    school = get_object_or_404(School, id=school_id, name=PRIMARY_SCHOOL_NAME)
    # This title is rendered only by the shared Admin topbar. School page
    # content continues to use the persisted School record below.
    context = _admin_context(request, "School", [])
    selected_calendar_id = request.GET.get('school_calendar_id')
    if request.method == 'POST' and request.POST.get('school_calendar_id'):
        selected_calendar_id = request.POST.get('school_calendar_id')
    selected_calendar = SchoolCalendar.objects.filter(pk=selected_calendar_id).first() if selected_calendar_id else None
    if not selected_calendar:
        selected_calendar = _active_school_calendar_for_new_workflows()
    ensure_salawag_grade_two_sections(school, selected_calendar)
    returning_students = []
    rollover_calendar = _active_school_calendar_for_new_workflows()
    if selected_calendar and rollover_calendar and selected_calendar.pk == rollover_calendar.pk:
        try:
            start_year = int(str(selected_calendar.school_year).split('-', 1)[0])
            previous_school_year = f'{start_year - 1}-{start_year}'
        except (TypeError, ValueError):
            previous_school_year = None
        previous_calendar = SchoolCalendar.objects.filter(school_year=previous_school_year).first() if previous_school_year else None
        if previous_calendar:
            prior = Enrollment.objects.filter(
                school=school, school_calendar=previous_calendar, status='completed', outcome='retained',
                student__role='student', student__is_archived=False, student__account_status='active',
            ).select_related('student', 'section', 'assigned_teacher', 'school_calendar')
            already_placed = Enrollment.objects.filter(
                school_calendar=selected_calendar, status__in=('active', 'awaiting_assignment'),
            ).values_list('student_id', flat=True)
            returning_students = list(prior.exclude(student_id__in=already_placed))
    if request.method == 'POST':
        if request.POST.get('action') == 'create_principal':
            form_data = {
                'first_name': request.POST.get('first_name', '').strip(),
                'middle_initial': request.POST.get('middle_initial', '').strip(),
                'last_name': request.POST.get('last_name', '').strip(),
                'suffix': request.POST.get('suffix', '').strip(),
                'email': request.POST.get('email', '').strip().lower(),
                'contact_no': request.POST.get('contact_no', '').strip(),
            }
            context['principal_form_data'] = form_data
            required = {
                'First name': form_data['first_name'],
                'Last name': form_data['last_name'],
                'Email address': form_data['email'],
            }
            missing = [label for label, value in required.items() if not value]
            if missing:
                context['principal_error'] = f"{', '.join(missing)} required."
            else:
                archived_principal = User.objects.filter(
                    role='principal', school_record=school, is_archived=True,
                ).order_by('-archived_at', '-id').first()
                if archived_principal and request.POST.get('confirm_replacement') != '1':
                    context['principal_error'] = 'Confirm replacement before creating a new Principal account.'
                    context['principal'] = _active_principal_for_school(school)
                else:
                    try:
                        with transaction.atomic():
                            locked_school = School.objects.select_for_update().get(pk=school.pk)
                            principal, temporary_password = _create_principal_account(
                                request,
                                locked_school,
                                form_data['first_name'],
                                form_data['middle_initial'],
                                form_data['last_name'],
                                form_data['suffix'],
                                form_data['email'],
                                form_data['contact_no'],
                            )
                            if archived_principal:
                                User.objects.select_for_update().get(pk=archived_principal.pk).delete()
                        email_sent = _try_send_principal_credentials_email(
                            request,
                            principal,
                            locked_school.name,
                            temporary_password,
                        )
                        if email_sent:
                            messages.success(
                                request,
                                "Principal account created successfully. Login credentials were sent to the Principal's email.",
                            )
                        else:
                            messages.warning(
                                request,
                                'Principal account created successfully, but the credentials email could not be sent. '
                                'Please verify the email configuration or resend the credentials later.',
                            )
                        return redirect('admin_school_detail', school_id=school.id)
                    except (ValueError, IntegrityError) as exc:
                        context['principal_error'] = str(exc) if isinstance(exc, ValueError) else 'This School already has an active Principal.'
            context['principal'] = _active_principal_for_school(school)
        else:
            context['principal_form_data'] = {}
    grouped = {grade: [] for grade in SCHOOL_GRADE_LEVELS}
    for section in _school_sections_queryset(school, selected_calendar):
        grouped.setdefault(section.grade_level, []).append(section)
    active_grade_two_sections = Section.objects.filter(
        school=school,
        school_calendar=selected_calendar,
        is_active=True,
        grade_level=NEW_USER_GRADE_LEVEL,
        teacher__isnull=False,
    ).select_related('teacher').order_by('section')
    teacher_assignment_map = {
        str(section.teacher_id): {
            'teacher_id': section.teacher_id,
            'teacher_name': f"{section.teacher.first_name} {section.teacher.last_name}".strip(),
            'section_id': section.id,
            'section_name': section.section,
        }
        for section in active_grade_two_sections
        if section.teacher_id
    }
    context.update({
        'school': school,
        'principal': context.get('principal', _active_principal_for_school(school)),
        'archived_principals': User.objects.filter(
            role='principal', school_record=school, is_archived=True,
        ).order_by('-archived_at', 'id'),
        'principal_form_data': context.get('principal_form_data', {}),
        'school_calendars': SchoolCalendar.objects.all().order_by('-is_active', '-updated_at', '-created_at'),
        'selected_calendar': selected_calendar,
        'sections_by_grade': grouped,
        'eligible_teachers': User.objects.filter(
            role='teacher', is_archived=False, school_record=school,
        ).order_by('last_name', 'first_name', 'custom_id'),
        'teacher_assignment_map': json.dumps(teacher_assignment_map),
        'returning_students': returning_students,
        'returning_school_calendar': selected_calendar,
    })
    return render(request, 'pabasa_app/admin_school.html', context)


@admin_required
@require_http_methods(["POST"])
def admin_school_section_update(request, section_id):
    section = _get_managed_section(section_id)
    if not section:
        return redirect('admin_school')
    action = str(request.POST.get('action') or '').strip().lower()
    if action == 'rename':
        name = str(request.POST.get('section') or '').strip().upper()
        if name:
            section.section = name
            section.class_name = f'{section.grade_level} - {name}'
            try:
                section.full_clean()
                section.save(update_fields=['section', 'class_name', 'updated_at'])
            except (ValidationError, IntegrityError):
                pass
    elif action == 'deactivate':
        section.is_active = False
        section.save(update_fields=['is_active', 'updated_at'])
    elif action == 'reactivate':
        section.is_active = True
        section.save(update_fields=['is_active', 'updated_at'])
    elif action in ('assign_teacher', 'change_teacher'):
        teacher_id = request.POST.get('teacher_id')
        teacher = User.objects.filter(id=teacher_id, role='teacher', is_archived=False, school_record_id=section.school_id).first()
        if not teacher:
            messages.error(request, 'Choose a valid active teacher from this school.')
        else:
            confirm_swap = str(request.POST.get('confirm_swap') or '').strip().lower() in {'1', 'true', 'yes', 'on'}
            selected_teacher_current_section = Section.objects.filter(
                school_id=section.school_id,
                school_calendar_id=section.school_calendar_id,
                is_active=True,
                teacher=teacher,
                grade_level=NEW_USER_GRADE_LEVEL,
            ).exclude(pk=section.pk).first()
            current_target_teacher = section.teacher
            if selected_teacher_current_section and current_target_teacher and current_target_teacher.id != teacher.id and not confirm_swap:
                messages.error(
                    request,
                    f"{teacher.first_name} {teacher.last_name} is currently assigned to {selected_teacher_current_section.section}. "
                    f"Swap assignments with the teacher currently assigned to {section.section}?",
                )
                return redirect('admin_school_detail', school_id=section.school_id)
            try:
                with transaction.atomic():
                    section_locked = Section.objects.select_for_update().get(pk=section.pk)
                    source_section = None
                    if selected_teacher_current_section:
                        source_section = Section.objects.select_for_update().get(pk=selected_teacher_current_section.pk)
                    if source_section and current_target_teacher and current_target_teacher.id != teacher.id:
                        other_teacher = current_target_teacher
                        source_section.teacher = other_teacher
                        section_locked.teacher = teacher
                        source_section.save(update_fields=['teacher', 'updated_at'])
                        section_locked.save(update_fields=['teacher', 'updated_at'])
                        for target in (source_section, section_locked):
                            Enrollment.objects.filter(
                                section=target, school_calendar=target.school_calendar,
                                status='active', is_active=True,
                            ).update(assigned_teacher=target.teacher)
                            target.sync_legacy_student_fields()
                        messages.success(
                            request,
                            f"{teacher.first_name} {teacher.last_name} and {other_teacher.first_name} {other_teacher.last_name} were swapped for {source_section.section} and {section_locked.section}.",
                        )
                    else:
                        if source_section and source_section.teacher_id == teacher.id:
                            source_section.unassign_teacher()
                        if action == 'change_teacher' or (section_locked.teacher_id and section_locked.teacher_id != teacher.id):
                            section_locked.assign_teacher(teacher, replace_existing=True)
                        else:
                            section_locked.assign_teacher(teacher, replace_existing=False)
                        Enrollment.objects.filter(
                            section=section_locked, school_calendar=section_locked.school_calendar,
                            status='awaiting_assignment', is_active=False,
                        ).update(assigned_teacher=teacher, status='active', is_active=True)
                        Enrollment.objects.filter(
                            section=section_locked, school_calendar=section_locked.school_calendar,
                            status='active', is_active=True,
                        ).update(assigned_teacher=teacher)
                        section_locked.sync_legacy_student_fields()
                        verb = 'changed' if action == 'change_teacher' else 'assigned'
                        messages.success(request, f'{teacher.first_name} {teacher.last_name} was {verb} for {section_locked.class_name}.')
            except ValidationError as exc:
                logger.warning(
                    'Admin teacher assignment rejected section_id=%s teacher_id=%s calendar_id=%s errors=%s',
                    section.id, teacher.id, section.school_calendar_id, exc.messages,
                )
                messages.error(request, '; '.join(str(error) for error in exc.messages) or 'Teacher assignment could not be saved.')
    if section.school_id:
        return redirect('admin_school_detail', school_id=section.school_id)
    return redirect('admin_school')

def _get_managed_section(section_id):
    """Retrieve a section by ID. Returns None if not found."""
    try:
        return Section.objects.get(id=section_id)
    except Section.DoesNotExist:
        return None

def _admin_sections_context(request, page_title):
    """
    Build context for admin class list view with search and filter.
    Supports search by class_code, class_name, subject, and teacher name.
    Supports filter by status (active, archived, all).
    """
    search_query = request.GET.get('q', '').strip()
    status_filter = request.GET.get('status', 'all').strip().lower()

    sections = Section.objects.all()
    
    if search_query:
        sections = sections.filter(
            Q(class_code__icontains=search_query) |
            Q(class_name__icontains=search_query) |
            Q(subject__icontains=search_query) |
            Q(teacher__first_name__icontains=search_query) |
            Q(teacher__last_name__icontains=search_query)
        )
    
    if status_filter == 'active':
        sections = sections.filter(is_active=True)
    elif status_filter == 'archived':
        sections = sections.filter(is_active=False)

    context = _admin_context(request, page_title, [
        'Class Name',
        'Subject',
        'Teacher',
        'Student Count',
        'Status',
        'Actions',
    ])
    context.update({
        'sections': sections.order_by('class_name'),
        'search_query': search_query,
        'status_filter': status_filter,
    })
    return context

def _admin_section_template_context(request, section, page_title):
    """Build context for section detail and edit templates."""
    student_count = section.get_student_count()
    enrolled_students = section.get_enrolled_students(active_only=True)
    enrollments = section.enrollments.filter(is_active=True).select_related('student').order_by('student__last_name', 'student__first_name')
    destination_sections = Section.objects.filter(
        school_id=section.school_id,
        school_calendar_id=section.school_calendar_id,
        school_calendar__is_active=True,
        is_active=True,
        grade_level=NEW_USER_GRADE_LEVEL,
    ).exclude(pk=section.pk).order_by('class_name', 'id')
    eligible_teachers = User.objects.filter(
        role='teacher', is_archived=False, school_record_id=section.school_id,
    ).order_by('last_name', 'first_name', 'custom_id')
    conflicting_teacher_ids = set(Section.objects.filter(
        school_calendar_id=section.school_calendar_id,
        is_active=True,
        grade_level=NEW_USER_GRADE_LEVEL,
        teacher__isnull=False,
    ).exclude(pk=section.pk).values_list('teacher_id', flat=True))
    
    context = _admin_context(request, page_title, [])
    context.update({
        'section': section,
        'teacher': section.teacher,
        'student_count': student_count,
        'enrolled_students': enrolled_students,
        'teacher_name': section.active_teacher_name(),
        'status': 'Active' if section.is_active else 'Archived',
        'enrollments': enrollments,
        'destination_sections': destination_sections,
        'eligible_teachers': eligible_teachers,
        'conflicting_teacher_ids': conflicting_teacher_ids,
    })
    return context

@admin_required
def admin_class_detail(request, section_id):
    """View class details including enrolled students."""
    section = _get_managed_section(section_id)
    if not section:
        return redirect('admin_classes')
    return render(request, 'pabasa_app/admin_class_detail.html', 
                  _admin_section_template_context(request, section, 'Class Details'))

@admin_required
@require_http_methods(["GET", "POST"])
def admin_class_edit(request, section_id):
    """Edit class information."""
    if request.method == 'GET':
        section = _get_managed_section(section_id)
        if not section:
            return redirect('admin_classes')
        if request.GET.get('edit') == '1':
            return render(request, 'pabasa_app/admin_class_edit.html', _admin_section_template_context(request, section, 'Edit Class'))
        return render(request, 'pabasa_app/admin_section_management.html', _admin_section_template_context(request, section, 'Section Management'))
    return _admin_edit_section(request, section_id)

def _admin_edit_section(request, section_id):
    """Handle GET/POST for section edit view."""
    section = _get_managed_section(section_id)
    if not section:
        return redirect('admin_classes')

    if request.method == 'POST':
        class_name = request.POST.get('class_name', '').strip()
        subject = request.POST.get('subject', '').strip()
        # Per-class `section` field removed from Section model — ignore any posted value
        header = request.POST.get('header', '').strip()
        description = request.POST.get('description', '').strip()

        # Validation
        if not class_name:
            context = _admin_section_template_context(request, section, 'Edit Class')
            context['error_message'] = 'Class name is required.'
            return render(request, 'pabasa_app/admin_class_edit.html', context, status=400)
        
        if not subject:
            context = _admin_section_template_context(request, section, 'Edit Class')
            context['error_message'] = 'Subject is required.'
            return render(request, 'pabasa_app/admin_class_edit.html', context, status=400)

        # Update section
        section.class_name = class_name
        section.subject = subject
        section.header = header
        section.description = description
        section.save()
        
        return redirect('admin_class_detail', section_id=section.id)

    return render(request, 'pabasa_app/admin_class_edit.html', 
                  _admin_section_template_context(request, section, 'Edit Class'))

@admin_required
@require_http_methods(["POST"])
def admin_class_deactivate(request, section_id):
    """Deactivate a class (soft delete with status flag)."""
    return _admin_deactivate_section(request, section_id)

def _admin_deactivate_section(request, section_id):
    """Handle POST for section deactivate action."""
    section = _get_managed_section(section_id)
    if not section:
        return redirect('admin_classes')

    action = request.POST.get('action', 'deactivate').strip().lower()
    
    if action == 'deactivate' and section.is_active:
        section.is_active = False
        section.save()
    elif action == 'reactivate' and not section.is_active:
        section.is_active = True
        section.save()

    return redirect('admin_classes')

