@principal_required
def principal_reports(request):
    """Principal Reports Page - Generate and view reports"""
    context = _principal_context(request, 'Reports')
    user = User.objects.filter(id=request.session.get('user_id')).first()
    analytics = _principal_analytics(user)

    report_type_labels = {
        'school': 'School Performance',
        'grade': 'Grade-Level',
        'assessment': 'Assessment',
    }

    selected_report_type = (request.GET.get('report_type') or 'school').strip().lower()
    selected_grade = NEW_USER_GRADE_LEVEL
    export_type = (request.GET.get('export') or '').strip().lower()
    headers, rows = _principal_report_preview_rows(analytics, selected_report_type, selected_grade)
    preview_rows = rows[:-2] if selected_report_type == 'school' else rows
    selected_report_label = f"{report_type_labels.get(selected_report_type, 'School Performance')} Report"
    selected_report_summary = 'School-wide participation, completion rate, and performance trends across the campus.'

    if selected_report_type == 'grade':
        if selected_grade:
            selected_report_label = f'{report_type_labels.get(selected_report_type, "School Performance")} Report - {selected_grade}'
            selected_report_summary = f'Grade-level performance data focused on {selected_grade}.'
        else:
            selected_report_summary = 'Grade-level comparison across all available grade levels.'
    elif selected_report_type == 'assessment':
        selected_report_summary = 'Assessment-specific results, completion status, and student performance by task.'

    if export_type == 'csv' or export_type == 'excel':
        return _principal_report_csv_response(selected_report_type, headers, rows)

    if export_type == 'pdf':
        return _principal_report_pdf_response(request, analytics, selected_report_type, selected_grade, headers, rows)

    context.update({
        **analytics,
        'report_types': [
            {'value': 'school', 'label': 'School Performance'},
            {'value': 'grade', 'label': 'Grade-Level'},
            {'value': 'assessment', 'label': 'Assessment'},
        ],
        'selected_report_type': selected_report_type,
        'selected_grade': selected_grade,
        'selected_report_label': selected_report_label,
        'report_preview_summary': selected_report_summary,
        'report_preview_count': len(preview_rows),
        'report_preview_headers': headers,
        'report_preview_rows': preview_rows,
    })
    return render(request, 'pabasa_app/principal_reports.html', context)

@csrf_protect
@require_http_methods(["GET", "POST"])
@principal_required
def principal_settings(request):
    """Principal Settings Page - School information and account settings"""
    user = User.objects.filter(id=request.session.get('user_id')).first()
    if not user:
        request.session.flush()
        return redirect('auth')

    context = _principal_context(request, 'Settings')
    notification_settings = _notification_settings_for_user(user)

    default_school_info = {
        'name': getattr(user, 'school', '') or '',
        'code': '',
        'municipality': '',
        'province': '',
        'district': '',
        'region': '',
        'address': '',
        'contact': getattr(user, 'contact_no', '') or '',
        'email': getattr(user, 'email', '') or '',
    }
    default_academic_settings = {
        'academic_year': '2024-2025',
        'term': '2',
        'school_year_start': '2024-06-03',
        'school_year_end': '2025-04-30',
    }

    school_info = _get_profile_dict(user, 'principal_school_info') or {}
    academic_settings = _get_profile_dict(user, 'principal_academic_settings') or {}
    principal_profile_info = _get_profile_dict(user, 'principal_profile_info') or {}
    if not isinstance(school_info, dict):
        school_info = {}
    if not isinstance(academic_settings, dict):
        academic_settings = {}
    if not isinstance(principal_profile_info, dict):
        principal_profile_info = {}

    if request.method == 'POST':
        action = request.POST.get('settings_action', '').strip()

        if action == 'save_school_info':
            school_info = {
                'name': request.POST.get('school_name', '').strip(),
                'code': request.POST.get('school_code', '').strip(),
                'municipality': request.POST.get('municipality', '').strip(),
                'province': request.POST.get('province', '').strip(),
                'district': request.POST.get('district', '').strip(),
                'region': request.POST.get('region', '').strip(),
                'address': request.POST.get('address', '').strip(),
                'contact': request.POST.get('contact', '').strip(),
                'email': request.POST.get('email', '').strip(),
                'logo': school_info.get('logo', ''),
            }
            _set_profile_dict(user, 'principal_school_info', school_info)
            context['settings_success'] = 'School information updated.'

        elif action == 'save_academic_year':
            academic_settings = {
                'academic_year': request.POST.get('academic_year', '').strip() or default_academic_settings['academic_year'],
                'term': request.POST.get('term', '').strip() or default_academic_settings['term'],
                'school_year_start': request.POST.get('school_year_start', '').strip() or default_academic_settings['school_year_start'],
                'school_year_end': request.POST.get('school_year_end', '').strip() or default_academic_settings['school_year_end'],
            }
            _set_profile_dict(user, 'principal_academic_settings', academic_settings)
            context['settings_success'] = 'Academic year settings updated.'

        elif action == 'change_password':
            current_password = request.POST.get('current_password', '')
            new_password = request.POST.get('new_password', '')
            confirm_password = request.POST.get('confirm_password', '')

            if not current_password or not new_password or not confirm_password:
                context['settings_error'] = 'All password fields are required.'
            elif not check_password(current_password, user.password_hash):
                context['settings_error'] = 'Current password is incorrect.'
            elif new_password != confirm_password:
                context['settings_error'] = 'New passwords do not match.'
            elif len(new_password) < 8:
                context['settings_error'] = 'Password must be at least 8 characters.'
            else:
                user.password_hash = make_password(new_password)
                user.save(update_fields=['password_hash', 'updated_at'])
                context['settings_success'] = 'Password changed successfully.'

        elif action == 'save_personal_info':
            first_name = request.POST.get('first_name', '').strip()
            last_name = request.POST.get('last_name', '').strip()
            middle_initial = request.POST.get('middle_initial', '').strip()
            email = request.POST.get('email', '').strip()
            contact_number = request.POST.get('contact_number', '').strip()
            position = request.POST.get('position', '').strip()

            if not first_name or not last_name:
                context['settings_error'] = 'First name and last name are required.'
            else:
                user.first_name = first_name
                user.last_name = last_name
                user.middle_initial = middle_initial if middle_initial else ''
                user.email = email
                user.contact_no = contact_number
                request.session['first_name'] = user.first_name
                request.session['last_name'] = user.last_name
                request.session['middle_initial'] = user.middle_initial
                user.save(update_fields=['first_name', 'last_name', 'middle_initial', 'email', 'contact_no', 'updated_at'])
                profile_info = _get_profile_dict(user, 'principal_profile_info') or {}
                if not isinstance(profile_info, dict):
                    profile_info = {}
                profile_info['position'] = position or 'Head Teacher/Principal II'
                _set_profile_dict(user, 'principal_profile_info', profile_info)
                context['settings_success'] = 'Personal information updated.'

        elif action == 'save_notifications':
            notification_settings = _posted_notification_settings(request)
            _set_profile_dict(user, 'notification_settings', notification_settings)
            context['settings_success'] = 'Notification preferences updated.'

        else:
            context['settings_error'] = 'Unknown settings action.'

    last_login_dt = user.updated_at if isinstance(user.updated_at, datetime) else datetime.fromisoformat(str(user.updated_at)) if user.updated_at else None
    account_created_dt = user.created_at if isinstance(user.created_at, datetime) else datetime.fromisoformat(str(user.created_at)) if user.created_at else None
    user_agent = request.META.get('HTTP_USER_AGENT', '')
    browser_device = _parse_user_agent(user_agent)
    context.update({
        'school_info': {**default_school_info, **school_info},
        'academic_settings': {**default_academic_settings, **academic_settings},
        'principal_profile_info': {
            'position': principal_profile_info.get('position', 'Head Teacher/Principal II'),
        },
        'first_name': user.first_name,
        'last_name': user.last_name,
        'middle_initial': user.middle_initial,
        'email': user.email,
        'contact_number': user.contact_no or '',
        'notification_settings': notification_settings,
        'last_login': last_login_dt.strftime('%B %d, %Y') if last_login_dt else 'N/A',
        'account_created': account_created_dt.strftime('%B %d, %Y') if account_created_dt else 'N/A',
        'browser_device': browser_device,
    })
    return render(request, 'pabasa_app/principal_settings.html', context)
@principal_required
@require_http_methods(["GET", "POST", "PUT", "PATCH", "DELETE"])
def principal_calendar(request):
    """School-local calendar management; global events are always read-only."""
    principal = _principal_school_user(request)
    school = principal.school_record if principal else None
    if request.method == "GET":
        qs = CalendarEvent.objects.filter(Q(scope=CalendarEvent.SCOPE_GLOBAL) | Q(scope__in=["", None], school__isnull=True) | Q(scope=CalendarEvent.SCOPE_SCHOOL, school=school)).order_by("start_date", "end_date")
        events = [_calendar_event_payload(e) | {"scope": e.scope or CalendarEvent.SCOPE_GLOBAL, "school_id": e.school_id} for e in qs]
        if request.GET.get("format") == "json" or request.headers.get("Accept", "").startswith("application/json"):
            return JsonResponse({"events": events})
        active_calendar, _, _ = _selected_school_calendar(request)
        widget = _calendar_month_view(active_calendar)
        context = _principal_context(request, "Calendar")
        context.update({"events": events, "events_json": json.dumps(events), "school": school, "active_school_calendar": active_calendar, "student_calendar_school_year": _calendar_school_year_label(active_calendar), "student_calendar_current_term": f"Term {active_calendar.current_term}" if active_calendar else "Not set", "calendar_weekday_labels": ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], "student_calendar_events_json": json.dumps(events), **widget})
        return render(request, "pabasa_app/principal_calendar.html", context)
    if request.method == "POST":
        try:
            if not school:
                return JsonResponse({"success": False, "error": "School not assigned. Local events cannot be created."}, status=403)
            if getattr(school, "status", "active") == "archived" or not getattr(school, "is_active", True):
                return JsonResponse({"success": False, "error": "Archived schools cannot create new local events."}, status=403)
            data = request.POST
            title = str(data.get("title", "")).strip()
            start_date = str(data.get("start_date", "")).strip()
            if not title:
                return JsonResponse({"success": False, "error": "Event Title is required."}, status=400)
            if not start_date:
                return JsonResponse({"success": False, "error": "Start Date is required."}, status=400)
            # Reuse the canonical Admin/Student calendar resolver (which uses
            # school-year bounds and falls back to the configured calendar),
            # rather than assuming is_active is authoritative.
            calendar, _, _ = _selected_school_calendar(request)
            if not calendar:
                return JsonResponse({"success": False, "error": "No active school calendar is configured."}, status=409)
            event = CalendarEvent(school_calendar=calendar, scope=CalendarEvent.SCOPE_SCHOOL, school=school, title=title, event_type="other", term=calendar.current_term or 1, start_date=start_date, end_date=str(data.get("end_date") or start_date), description=data.get("description", ""), is_published=True)
            event.full_clean()
            event.save()
            return JsonResponse({"success": True, "event": _calendar_event_payload(event) | {"scope": event.scope, "school_id": event.school_id}}, status=201)
        except ValidationError as exc:
            logger.warning("Principal calendar event validation failed: %s", exc.message_dict if hasattr(exc, 'message_dict') else exc.messages)
            return JsonResponse({"success": False, "error": "The event details are invalid. Please check the dates and try again."}, status=400)
        except Exception as exc:
            logger.exception("Principal calendar event creation failed type=%s", type(exc).__name__)
            return JsonResponse({"success": False, "error": "Unable to save the school event right now."}, status=500)
    event_id = request.POST.get("event_id") or request.GET.get("event_id")
    event = CalendarEvent.objects.filter(pk=event_id, scope=CalendarEvent.SCOPE_SCHOOL, school=school).first()
    if not event:
        return JsonResponse({"success": False, "error": "Event not found or not owned by your school."}, status=404)
    if request.method == "DELETE":
        event.delete(); return JsonResponse({"success": True})
    for field in ("title", "event_type", "start_date", "end_date", "description"):
        if field in request.POST: setattr(event, field, request.POST[field])
    event.save(); return JsonResponse({"success": True})


# ============================================================================
# Story Response Activity Views
# ============================================================================

def _is_story_response_material(material):
    """Check if a material is a Story Response activity."""
    if not material or not isinstance(material, Material):
        return False
    content_json = material.content_json if isinstance(material.content_json, dict) else {}
    return content_json.get('activity_type') == 'story_response'


@require_http_methods(["GET"])
def get_published_stories_api(request):
    """
    API endpoint to get all published Story Reading activities for the teacher's classes.
    Returns a list of published stories that can be used as sources for Story Response activities.
    """
    user = User.objects.filter(id=request.session.get('user_id'), role='teacher', is_archived=False).first()
    if not user:
        return JsonResponse({'success': False, 'error': 'Teacher not found.'}, status=404)
    
    # Get published story reading materials the teacher has access to
    published_stories = Material.objects.filter(
        teacher=user,
        status='published',
        is_active=True,
    ).select_related('teacher')
    
    # Filter to only story reading materials
    stories = []
    for material in published_stories:
        if _is_story_reading_material(material):
            content_json = material.content_json or {}
            story_data = {
                'id': material.id,
                'material_id': f'material-{material.id}',
                'title': str(content_json.get('storyTitle') or material.title or '').strip(),
                'language': str(content_json.get('language') or material.language or 'English').strip(),
                'story_key': str(content_json.get('storyKey') or '').strip(),
                'story_text': str(content_json.get('storyText') or material.content_text or '').strip(),
                'text_preview': str(content_json.get('storyText') or material.content_text or '')[:200].strip(),
                'created_at': material.created_at.isoformat() if material.created_at else None,
                'teacher': ' '.join(part for part in [
                    getattr(material.teacher, 'first_name', ''),
                    getattr(material.teacher, 'last_name', ''),
                ] if part).strip() if material.teacher else 'System',
            }
            stories.append(story_data)
    
    # Sort by creation date, newest first
    stories.sort(key=lambda x: x['created_at'] or '', reverse=True)
    
    return JsonResponse({
        'success': True,
        'stories': stories,
        'total': len(stories),
    })


@csrf_protect
@require_http_methods(["POST"])
def get_story_response_prompts_api(request):
    """
    API endpoint to get suggested response prompts for a given story.
    """
    try:
        payload = json.loads(request.body or '{}')
    except (TypeError, ValueError):
        return JsonResponse({'success': False, 'error': 'Invalid JSON.'}, status=400)
    
    from .story_response_prompts import RESPONSE_PROMPT_CATEGORIES, SUGGESTED_PROMPTS, STORY_SPECIFIC_PROMPTS
    
    story_id = payload.get('story_id')
    language = str(payload.get('language', 'English')).strip()
    
    if not story_id:
        return JsonResponse({'success': False, 'error': 'story_id is required.'}, status=400)
    
    # Get the story material
    story_material = Material.objects.filter(id=story_id, status='published').first()
    if not story_material or not _is_story_reading_material(story_material):
        return JsonResponse({'success': False, 'error': 'Story not found or not published.'}, status=404)
    
    # Get the story key
    content_json = story_material.content_json or {}
    story_key = content_json.get('storyKey') or ''
    
    # Get prompts by category
    prompts_by_category = {}
    language_prompts = SUGGESTED_PROMPTS.get(language, SUGGESTED_PROMPTS.get('English', {}))
    
    for category, items in language_prompts.items():
        category_info = RESPONSE_PROMPT_CATEGORIES.get(category, {})
        prompts_by_category[category] = {
            'category': category,
            'emoji': category_info.get('emoji', ''),
            'label': category_info.get('label', ''),
            'description': category_info.get('description', ''),
            'prompts': [{'text': item, 'source': 'suggested', 'type': 'general'} for item in items]
        }
    
    # Add story-specific prompts
    if story_key:
        story_specific = STORY_SPECIFIC_PROMPTS.get(story_key, {})
        if story_specific:
            for category, items in story_specific.get('prompts', {}).items():
                if category not in prompts_by_category:
                    category_info = RESPONSE_PROMPT_CATEGORIES.get(category, {})
                    prompts_by_category[category] = {
                        'category': category,
                        'emoji': category_info.get('emoji', ''),
                        'label': category_info.get('label', ''),
                        'description': category_info.get('description', ''),
                        'prompts': []
                    }
                prompts_by_category[category]['prompts'].extend([
                    {'text': item, 'source': 'suggested', 'type': 'story_specific'}
                    for item in items
                ])
    
    return JsonResponse({
        'success': True,
        'categories': RESPONSE_PROMPT_CATEGORIES,
        'prompts_by_category': prompts_by_category,
    })


def story_response_page(request):
    """Render the student-facing Story Response activity page."""
    access_response = _enforce_student_access_for_request(request)
    if access_response:
        return access_response
    
    _, material_id = _parse_prefixed_id(request.GET.get('id') or request.GET.get('material_id'))
    material = Material.objects.filter(pk=material_id).first() if material_id else None
    
    if not material or not _is_story_response_material(material):
        return redirect('assessment')
    
    access_response = _enforce_student_access_for_request(request, material=material)
    if access_response:
        return access_response
    
    content_json = material.content_json or {}
    source_story_id = content_json.get('source_story_reading_material_id')
    source_story = Material.objects.filter(id=source_story_id).first() if source_story_id else None
    
    if not source_story or not _is_story_reading_material(source_story):
        return redirect('assessment')
    
    source_content = source_story.content_json or {}
    student = User.objects.filter(id=request.session.get('user_id'), role='student').first()
    
    activity_payload = {
        'id': material.id,
        'material_id': f'material-{material.id}',
        'title': str(content_json.get('activity_title') or material.title or 'Story Response').strip(),
        'source_story_id': source_story.id,
        'source_story_title': str(source_content.get('storyTitle') or source_story.title or '').strip(),
        'source_story_text': str(source_content.get('storyText') or source_story.content_text or '').strip(),
        'language': str(content_json.get('story_language') or source_content.get('language') or 'English').strip(),
        'response_prompt': str(content_json.get('response_prompt') or '').strip(),
        'prompt_category': str(content_json.get('prompt_category') or '').strip(),
        'prompt_source': str(content_json.get('prompt_source') or 'suggested').strip(),
        'host_character': str(content_json.get('host_character') or 'female').strip(),
        'read_aloud_enabled': bool(content_json.get('read_aloud_enabled', True)),
        'voice_recording_enabled': bool(content_json.get('voice_recording_enabled', True)),
        'student_first_name': str(student.first_name or '').strip().split()[0] if student and student.first_name else 'Friend',
        'student_avatar_set': 'male' if str(getattr(student, 'sex', '')).strip().lower().startswith('m') else 'female',
        'assigned_week': material.assigned_week,
        # Story Response is an independent learner activity, like Story Reading.
        'return_url': reverse('assessment'),
    }
    
    return render(request, 'pabasa_app/story_response_page.html', {
        'story_response_data': json.dumps(activity_payload),
    })


@csrf_protect
@require_http_methods(["POST"])
def story_response_submit(request):
    """Submit a student's story response."""
    if request.content_type and request.content_type.startswith('multipart/form-data'):
        payload = request.POST
    else:
        try:
            payload = json.loads(request.body or '{}')
        except (TypeError, ValueError):
            return JsonResponse({'success': False, 'error': 'Invalid JSON.'}, status=400)
    
    user = User.objects.filter(id=request.session.get('user_id'), role='student', is_archived=False).first()
    if not user:
        return JsonResponse({'success': False, 'error': 'Student not found.'}, status=404)
    
    _, material_id = _parse_prefixed_id(payload.get('material_id'))
    material = Material.objects.filter(pk=material_id).first() if material_id else None
    
    if not material or not _is_story_response_material(material):
        return JsonResponse({'success': False, 'error': 'Activity not found.'}, status=404)
    access_response = _enforce_student_access_for_request(request, material=material)
    if access_response:
        return access_response
    
    student_section = next((
        section for section in Section.objects.filter(is_active=True).select_related('school_calendar')
        if section.has_student(user, active_only=True)
    ), None)
    if not student_section:
        return JsonResponse({'success': False, 'error': 'You are not enrolled in an active class.'}, status=403)
    source_story_id = (material.content_json or {}).get('source_story_reading_material_id')
    source_story = Material.objects.filter(pk=source_story_id).first() if source_story_id else None
    if not source_story or not _is_story_reading_material(source_story):
        return JsonResponse({'success': False, 'error': 'The activity story is unavailable.'}, status=400)
    audio = request.FILES.get('audio')
    if not audio:
        return JsonResponse({'success': False, 'error': 'A recording is required.'}, status=400)
    duration = payload.get('duration_seconds')
    try:
        duration = max(0, int(duration)) if duration is not None else None
    except (TypeError, ValueError):
        duration = None
    submission, _ = StoryResponseSubmission.objects.update_or_create(
        student=user,
        material=material,
        defaults={
            'enrollment': Enrollment.objects.filter(student=user, section=student_section, status='active', is_active=True).order_by('id').first(),
            'story_material': source_story,
            'prompt': str((material.content_json or {}).get('response_prompt') or '').strip(),
            'response_text': str(payload.get('response_text') or '').strip(),
            'duration_seconds': duration,
            'status': 'pending',
            'grade': None,
            'graded_by': None,
            'graded_at': None,
        },
    )
    submission.audio_file.save(audio.name, audio, save=True)
    
    return JsonResponse({
        'success': True,
        'message': 'Your response has been recorded.',
        'submitted_at': submission.submitted_at.isoformat(),
        'submission_id': submission.id,
    })


def _story_response_review_payload(submission):
    content = submission.story_material.content_json if submission.story_material_id else {}
    return {
        'id': submission.id,
        'student_id': submission.student_id,
        'student_name': f'{submission.student.first_name} {submission.student.last_name}'.strip() or submission.student.custom_id,
        'status': 'Graded' if submission.grade is not None else 'Pending Grade',
        'recording_available': bool(submission.audio_file),
        'recording_url': reverse('teacher_story_response_audio', args=[submission.id]) if submission.audio_file else None,
        'response_text': submission.response_text,
        'duration_seconds': submission.duration_seconds,
        'story_title': str(content.get('storyTitle') or submission.story_material.title or '').strip(),
        'prompt': submission.prompt,
        'grade': submission.grade,
        'submitted_at': submission.submitted_at.isoformat(),
    }


@require_http_methods(["GET"])
@login_required(role='teacher')
def teacher_story_response_review(request):
    _, material_id = _parse_prefixed_id(request.GET.get('material_id'))
    material = Material.objects.filter(pk=material_id).first() if material_id else None
    teacher = User.objects.filter(pk=request.session.get('user_id'), role='teacher', is_archived=False).first()
    if not material or not _is_story_response_material(material):
        return JsonResponse({'success': False, 'error': 'Response to Story activity not found.'}, status=404)
    if not teacher or not _teacher_can_access_material(teacher, material):
        return JsonResponse({'success': False, 'error': 'Access denied.'}, status=403)
    section_ids = set(material.assigned_sections.filter(is_active=True).values_list('id', flat=True))
    if material.section_id:
        section_ids.add(material.section_id)
    for course in material.courses.filter(is_active=True):
        section_ids.update(course.sections.filter(is_active=True).values_list('id', flat=True))
    student_ids = set()
    for section in Section.objects.filter(id__in=section_ids, is_active=True):
        student_ids.update(entry.get('student_id') for entry in section.get_enrolled_students(active_only=True) if entry.get('student_id'))
    submissions = {row.student_id: row for row in StoryResponseSubmission.objects.filter(material=material, student_id__in=student_ids).select_related('student', 'story_material')}
    students = User.objects.filter(id__in=student_ids, role='student').order_by('last_name', 'first_name')
    rows = []
    for student in students:
        row = submissions.get(student.id)
        rows.append(_story_response_review_payload(row) if row else {
            'student_id': student.id,
            'student_name': f'{student.first_name} {student.last_name}'.strip() or student.custom_id,
            'status': 'No Submission', 'recording_available': False, 'recording_url': None,
            'story_title': '', 'prompt': '', 'grade': None,
        })
    return JsonResponse({'success': True, 'activity': {'id': material.id, 'title': material.title}, 'submissions': rows})


@csrf_protect
@require_http_methods(["POST"])
@login_required(role='teacher')
def teacher_story_response_grade(request):
    try:
        payload = json.loads(request.body or '{}')
        submission = StoryResponseSubmission.objects.select_related('material').get(pk=payload.get('submission_id'))
        teacher = User.objects.filter(pk=request.session.get('user_id'), role='teacher', is_archived=False).first()
        if not teacher or not _teacher_can_access_material(teacher, submission.material):
            return JsonResponse({'success': False, 'error': 'Access denied.'}, status=403)
        grade = int(payload.get('grade'))
        if grade < 0 or grade > 5:
            raise ValueError
    except (TypeError, ValueError, StoryResponseSubmission.DoesNotExist):
        return JsonResponse({'success': False, 'error': 'A valid submission and grade from 0 to 5 are required.'}, status=400)
    submission.grade = grade
    submission.status = 'graded'
    submission.graded_by = teacher
    submission.graded_at = timezone.now()
    submission.save(update_fields=['grade', 'status', 'graded_by', 'graded_at', 'updated_at'])
    return JsonResponse({'success': True, 'submission': _story_response_review_payload(submission)})


@require_http_methods(["GET"])
@login_required(role='teacher')
def teacher_story_response_audio(request, submission_id):
    submission = StoryResponseSubmission.objects.select_related('material').filter(pk=submission_id).first()
    teacher = User.objects.filter(pk=request.session.get('user_id'), role='teacher', is_archived=False).first()
    if not submission or not submission.audio_file or not teacher or not _teacher_can_access_material(teacher, submission.material):
        return HttpResponseForbidden('Recording unavailable.')
    response = FileResponse(submission.audio_file.open('rb'), content_type='audio/webm')
    response['Content-Disposition'] = 'inline'
    return response
